CREATE TABLE users (
  id    BIGINT PRIMARY KEY,
  email TEXT NOT NULL UNIQUE
);

CREATE TABLE orders (
  id      BIGINT PRIMARY KEY,
  user_id BIGINT NOT NULL REFERENCES users (id),   -- foreign key
  total   NUMERIC NOT NULL CHECK (total >= 0)
);

const users: { email: string }[] = [];
const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));

async function signUp(email: string, who: string) {
  const exists = users.some((u) => u.email === email); // 1. check
  await sleep(10);                                     // gap: other requests run here
  if (exists) {
    console.log(`${who}: rejected`);
    return;
  }
  users.push({ email });                               // 2. insert
  console.log(`${who}: created`);
}

async function main() {
  await Promise.all([
    signUp("min@example.com", "request A"),
    signUp("min@example.com", "request B"),
  ]);
  console.log(users.length);
}
main();

