// db and isUniqueViolation are hypothetical helpers.
// How a driver reports a unique violation (error code, class) differs by driver.
async function signUp(email: string) {
  try {
    await db.insertUser(email);              // the UNIQUE constraint makes the final decision
    return { status: 201 };
  } catch (err) {
    if (isUniqueViolation(err)) return { status: 409 };
    throw err;                               // anything else is a real failure
  }
}

-- emails that appear more than once (HAVING filters groups after GROUP BY)
SELECT email, count(*) FROM users GROUP BY email HAVING count(*) > 1;

-- orders whose user_id points at no user (orphans)
SELECT o.id FROM orders o LEFT JOIN users u ON u.id = o.user_id WHERE u.id IS NULL;
